if (ADMIN_PASSWORD.length < 12 && process.env.NODE_ENV !== 'test') throw new Error('启动前必须通过 ADMIN_PASSWORD 提供至少 12 位测试密码');
const SESSION_TTL = 1000 * 60 * 60 * 8;
const sessions = new Map();
const demoProducts = [
  { id: 'F', slug: 'fu', name: '福 · 把喜气写进日子', type: '手写原作', category: '喜事', craft: '手写，演示装裱', material: '宣纸（演示）', size: '斗方（演示）', framing: '待确认', price: 99, stock: 1, unique: true, image: '/assets/fu.svg', description: '春节、乔迁与日常祝福场景的演示商品。', status: '演示数据', published: true, currency: 'CNY', specs: [{ id: 'standard', label: '演示标准斗方', size: '斗方（演示）', material: '宣纸（演示）', craft: '手写，演示装裱', framing: '待确认' }] },
  { id: 'L', slug: 'lu', name: '禄 · 给日子一份笃定', type: '手写定制', category: '日子', craft: '手写，装裱待确认', material: '宣纸（演示）', size: '斗方（演示）', framing: '待确认', price: 299, stock: 3, unique: false, image: '/assets/lu.svg', description: '适合书房与日常自勉的演示定制入口。', status: '演示数据', published: true, currency: 'CNY', specs: [{ id: 'standard', label: '演示标准斗方', size: '斗方（演示）', material: '宣纸（演示）', craft: '手写，装裱待确认', framing: '待确认' }] },
  { id: 'S', slug: 'shou', name: '寿 · 写给重要的人', type: '手写原作', category: '喜事', craft: '手写，装裱待确认', material: '宣纸（演示）', size: '四尺条（演示）', framing: '待确认', price: 599, stock: 1, unique: true, image: '/assets/shou.svg', description: '祝寿与家人礼赠场景的演示商品。', status: '演示数据', published: true, currency: 'CNY', specs: [{ id: 'standard', label: '演示标准四尺条', size: '四尺条（演示）', material: '宣纸（演示）', craft: '手写，装裱待确认', framing: '待确认' }] },
  { id: 'X', slug: 'xi', name: '喜 · 喜事要同乐', type: '艺术衍生品', category: '喜事', craft: '授权印品（演示）', material: '卡纸（演示）', size: 'A4（演示）', framing: '不含装裱（演示）', price: 59, stock: 20, unique: false, image: '/assets/xi.svg', description: '喜庆礼赠场景的演示衍生品，非手写原作。', status: '演示数据', published: true, currency: 'CNY', specs: [{ id: 'standard', label: '演示 A4 印品', size: 'A4（演示）', material: '卡纸（演示）', craft: '授权印品（演示）', framing: '不含装裱（演示）' }] },
  { id: 'C', slug: 'cai', name: '财 · 好运写给你', type: '艺术衍生品', category: '日子', craft: '授权印品（演示）', material: '卡纸（演示）', size: 'A4（演示）', framing: '不含装裱（演示）', price: 39, stock: 30, unique: false, image: '/assets/cai.svg', description: '轻量情绪语录产品演示，非手写原作。', status: '演示数据', published: true, currency: 'CNY', specs: [{ id: 'standard', label: '演示 A4 印品', size: 'A4（演示）', material: '卡纸（演示）', craft: '授权印品（演示）', framing: '不含装裱（演示）' }] }
];

await mkdir(DATA_DIR, { recursive: true });
const sqlite = new DatabaseSync(path.join(DATA_DIR, 'xiaominart.sqlite'));
sqlite.exec(`PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, access_token TEXT UNIQUE NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS custom_requests (id TEXT PRIMARY KEY, request_number TEXT UNIQUE NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, name TEXT NOT NULL, metadata TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency (kind TEXT NOT NULL, idem_key TEXT NOT NULL, digest TEXT NOT NULL, response_status INTEGER NOT NULL, response_body TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(kind, idem_key));`);
const normalizeProduct = product => ({ currency: 'CNY', published: true, unique: false, framing: '待确认', specs: [{ id: 'standard', label: '演示标准规格', size: product.size || '待确认', material: product.material || '待确认', craft: product.craft || '待确认', framing: product.framing || '待确认' }], ...product, stock: Number.isSafeInteger(product.stock) ? product.stock : 0 });
const seedCount = sqlite.prepare('SELECT COUNT(*) AS count FROM products').get().count;
if (!seedCount) for (const product of demoProducts) sqlite.prepare('INSERT INTO products (id, data) VALUES (?, ?)').run(product.id, JSON.stringify(product));
const db = {
  get products() { return sqlite.prepare('SELECT data FROM products ORDER BY rowid').all().map(row => normalizeProduct(JSON.parse(row.data))); },
  get orders() { return sqlite.prepare('SELECT data FROM orders ORDER BY rowid').all().map(row => JSON.parse(row.data)); },
  get customRequests() { return sqlite.prepare('SELECT data FROM custom_requests ORDER BY rowid').all().map(row => JSON.parse(row.data)); },
  get submissions() { return sqlite.prepare('SELECT data FROM submissions ORDER BY rowid').all().map(row => JSON.parse(row.data)); },
  get events() { return sqlite.prepare('SELECT id,name,metadata,created_at FROM events ORDER BY rowid').all().map(row => ({ id: row.id, name: row.name, metadata: JSON.parse(row.metadata), createdAt: row.created_at })); }
};
function productById(id) { return db.products.find(product => product.id === String(id)); }
function publicProduct(product) { return { ...normalizeProduct(product), specs: normalizeProduct(product).specs.map(spec => ({ ...spec })) }; }
function saveProduct(product) { sqlite.prepare('UPDATE products SET data = ? WHERE id = ?').run(JSON.stringify(normalizeProduct(product)), product.id); }
function saveOrder(order) { sqlite.prepare('INSERT INTO orders (id,access_token,data) VALUES (?,?,?)').run(order.id, order.accessToken, JSON.stringify(order)); }
function updateOrder(order) { sqlite.prepare('UPDATE orders SET data = ? WHERE id = ?').run(JSON.stringify(order), order.id); }
function saveCustom(request) { sqlite.prepare('INSERT INTO custom_requests (id,request_number,data) VALUES (?,?,?)').run(request.id, request.requestNumber, JSON.stringify(request)); }
function updateCustom(request) { sqlite.prepare('UPDATE custom_requests SET data = ? WHERE id = ?').run(JSON.stringify(request), request.id); }
function saveSubmission(item) { sqlite.prepare('INSERT INTO submissions (id,data) VALUES (?,?)').run(item.id, JSON.stringify(item)); }
function saveEvent(name, metadata = {}) { sqlite.prepare('INSERT INTO events (id,name,metadata,created_at) VALUES (?,?,?,?)').run(randomUUID(), name, JSON.stringify(metadata), new Date().toISOString()); }
function json(res, status, payload) { res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }); if (status !== 204) res.end(JSON.stringify(payload)); else res.end(); }
function html(res, body, status = 200) { res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Content-Security-Policy': "default-src 'self'; style-src 'self' https://fonts.googleapis.com 'unsafe-inline'; font-src https://fonts.gstatic.com; img-src 'self' data:; script-src 'self' 'unsafe-inline'" }); res.end(body); }
function redirect(res, location) { res.writeHead(302, { Location: location }); res.end(); }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char])); }
function safeJson(value) { return JSON.stringify(value).replace(/[<>&\u2028\u2029]/g, char => ({ '<': '\\u003C', '>': '\\u003E', '&': '\\u0026', '\u2028': '\\u2028', '\u2029': '\\u2029' }[char])); }
function parseCookies(req) { const result = {}; for (const pair of String(req.headers.cookie || '').split(';')) { const index = pair.indexOf('='); if (index < 1) continue; const key = pair.slice(0, index).trim(); const value = pair.slice(index + 1).trim(); try { result[key] = decodeURIComponent(value); } catch { continue; } } return result; }
function token() { return randomBytes(24).toString('hex'); }
function orderNumber(prefix) { return `${prefix}-${new Date().toISOString().slice(0, 10).replaceAll('-', '')}-${randomBytes(3).toString('hex').toUpperCase()}`; }
function digest(value) { return createHash('sha256').update(JSON.stringify(value)).digest('hex'); }
function requestKey(req, fallback) { const key = String(req.headers['idempotency-key'] || fallback || '').trim(); return key && /^[A-Za-z0-9._:-]{8,120}$/.test(key) ? key : null; }
function authenticated(req) { const session = sessions.get(parseCookies(req).xiaominart_session); return Boolean(session && session.expires > Date.now()); }
function requireAuth(req, res) { if (!authenticated(req)) { json(res, 401, { error: '需要管理员登录' }); return false; } return true; }
async function body(req) { let text = ''; for await (const chunk of req) { text += chunk; if (text.length > 150000) return null; } try { return text ? JSON.parse(text) : {}; } catch { return null; } }
function getIdempotent(kind, key, value) { const row = sqlite.prepare('SELECT digest,response_status,response_body FROM idempotency WHERE kind=? AND idem_key=?').get(kind, key); if (!row) return null; if (row.digest !== digest(value)) return { conflict: true }; return { status: row.response_status, body: JSON.parse(row.response_body) }; }
function saveIdempotent(kind, key, value, status, response) { sqlite.prepare('INSERT INTO idempotency(kind,idem_key,digest,response_status,response_body,created_at) VALUES (?,?,?,?,?,?)').run(kind, key, digest(value), status, JSON.stringify(response), new Date().toISOString()); }
function begin() { sqlite.exec('BEGIN IMMEDIATE'); }
function commit() { sqlite.exec('COMMIT'); }
function rollback() { try { sqlite.exec('ROLLBACK'); } catch {} }
function validateCustomer(customer) { if (!customer || typeof customer !== 'object') return null; const name = typeof customer.name === 'string' ? customer.name.trim().slice(0, 80) : ''; const contact = typeof customer.contact === 'string' ? customer.contact.trim().slice(0, 120) : ''; const address = typeof customer.address === 'string' ? customer.address.trim().slice(0, 240) : ''; return name && contact && address ? { name, contact, address } : null; }
function validateItems(raw) { if (!Array.isArray(raw) || !raw.length || raw.length > 50) return null; const merged = new Map(); for (const item of raw) { if (!item || typeof item !== 'object' || typeof item.id !== 'string' || typeof item.quantity !== 'number' || !Number.isSafeInteger(item.quantity) || item.quantity < 1) return null; const specId = typeof item.specId === 'string' && item.specId.length <= 80 ? item.specId : 'standard'; const key = `${item.id}\u0000${specId}`; const previous = merged.get(key); merged.set(key, { id: item.id, specId, quantity: (previous?.quantity || 0) + item.quantity }); } return [...merged.values()]; }
function findSpec(product, specId) { const specs = Array.isArray(product.specs) ? product.specs : []; return specs.find(spec => spec.id === specId) || specs[0]; }
function orderPreview(data) { const items = validateItems(data?.items); const customer = validateCustomer(data?.customer); const payment = data?.payment; if (!customer || !items || !['success', 'failure', 'cancelled'].includes(payment)) return { error: '客户信息、购物车或模拟支付结果无效' }; const resolved = []; let total = 0; for (const item of items) { const product = productById(item.id); if (!product || !product.published) return { error: `商品 ${escapeHtml(item.id)} 当前不可售` }; if (product.unique && (product.stock < 0 || product.stock > 1 || item.quantity !== 1)) return { error: `独件商品 ${escapeHtml(item.id)} 只能购买 1 件` }; if (item.quantity > product.stock) return { error: `商品 ${escapeHtml(item.id)} 库存不足，请刷新后重试` }; const spec = findSpec(product, item.specId); const snapshot = { id: product.id, slug: product.slug, name: product.name, type: product.type, specId: spec.id, specLabel: spec.label, size: spec.size, material: spec.material, craft: spec.craft, framing: spec.framing, price: product.price, currency: product.currency, quantity: item.quantity, snapshotAt: new Date().toISOString() }; resolved.push(snapshot); total += product.price * item.quantity; } return { customer, items: resolved, total, payment }; }
function stateText(orderStatus) { return ({ pending: '待处理', paid: '模拟支付成功', failed: '模拟支付失败', cancelled: '已取消', fulfilled: '已完成' })[orderStatus] || '未知状态'; }
function allowedOrderTransition(from, to) { return ({ pending: ['paid', 'failed', 'cancelled'], paid: ['fulfilled', 'cancelled'], failed: [], cancelled: [], fulfilled: [] })[from]?.includes(to) || false; }
function productCard(product) { const p = publicProduct(product); return `<article class="product-card" data-category="${escapeHtml(p.category)}" data-type="${escapeHtml(p.type)}" data-price="${p.price}"><a href="/shop/${escapeHtml(p.slug)}"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}（演示素材）"></a><div class="eyebrow">${escapeHtml(p.type)} · ${escapeHtml(p.status)}</div><h3><a href="/shop/${escapeHtml(p.slug)}">${escapeHtml(p.name)}</a></h3><p>${escapeHtml(p.description)}</p><div class="card-bottom"><span class="demo-price">演示价 ¥${p.price}</span><a href="/shop/${escapeHtml(p.slug)}">查看详情 →</a></div></article>`; }
function nav() { return `<div class="testbar">测试站：商品与价格可能为演示数据，不接受真实付款</div><header class="nav"><a class="brand" href="/">小民艺术 <span>XIAOMINART</span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-menu">菜单</button><nav id="site-menu"><a href="/shop">挑一幅字</a><a href="/custom">定制我的心意</a><a href="/craft">工艺与故事</a><a href="/about">关于小民</a><a href="/contact">联系帮助</a><a href="/inbox">小民信箱</a><a href="/good-news">小民喜报</a><a class="cart-link" href="/cart">购物车 <b id="cart-count">0</b></a></nav></header>`; }
function footer() { return `<footer class="footer"><div><strong>把日子，写成字。</strong><p>心事有人听 · 喜事有人乐。</p></div><div class="footer-links"><a href="/privacy">隐私说明</a><a href="/terms">销售条款</a><a href="/shipping">配送说明</a><a href="/after-sales">售后说明</a></div><div class="muted">本测试站使用演示商品、虚拟客户与模拟支付。未修改正式域名。</div></footer>`; }
function pageShell(title, content, scripts = '') { return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="小民艺术 xiaominART 测试站"><title>${escapeHtml(title)}｜小民艺术测试站</title><link rel="stylesheet" href="/styles.css"></head><body>${content}${scripts}<script>document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const nav=document.querySelector('#site-menu');const open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});</script></body></html>`; }
function cartScript() { return `<script>function cartRead(){try{const value=JSON.parse(localStorage.getItem('xiaominart_cart')||'[]');return Array.isArray(value)?value.filter(i=>i&&typeof i.id==='string'&&Number.isSafeInteger(i.quantity)&&i.quantity>0):[]}catch{return[]}}function updateCartCount(){const el=document.querySelector('#cart-count');if(el)el.textContent=String(cartRead().reduce((n,i)=>n+i.quantity,0))}updateCartCount()</script>`; }
function homePage() { return pageShell('把日子，写成字。', `${nav()}<main><section class="hero"><div class="hero-copy"><div class="eyebrow">小民艺术 XIAOMINART · 测试版</div><h1>把日子，写成字。</h1><p class="lead">心事有人听 · 喜事有人乐。给自己一句自勉，给家人一份祝福，也可以告诉小民，你想写给谁。</p><div class="actions"><a class="button" href="/shop">挑一幅字</a><a class="button secondary" href="/custom">定制我的心意</a></div></div><div class="hero-art"><div class="seal">小<br>民</div><div class="ink-line">让每一个普通人的日子<br>都有一笔认真落下。</div><span>待替换真实作品素材</span></div></section><section class="trust-grid"><div><b>先听故事</b><span>再推荐内容与规格</span></div><div><b>工艺说清楚</b><span>原作、定制、印品分开标注</span></div><div><b>测试可追踪</b><span>订单与定制需求后台可查</span></div></section><section class="section"><div class="section-heading"><div><div class="eyebrow">按喜好挑选</div><h2>福禄寿喜财，先从一句话开始。</h2></div><a href="/shop">查看全部 →</a></div><div class="product-grid">${db.products.filter(p=>p.published).map(productCard).join('')}</div></section><section class="split-section"><div><div class="eyebrow">定制指南</div><h2>你的话，小民认真听。</h2><p>告诉我写给谁、挂在哪里、想说什么。故事可选，默认私密；需求提交后生成编号，由后台继续处理。</p><a class="text-link" href="/custom">提交定制需求 →</a></div><div class="note-card"><span>是的小民</span><p>我不替大师写字，<br>我替每一个普通人写字。</p></div></section></main>${footer()}${cartScript()}`); }
function shopPage() { const products = db.products.filter(p=>p.published); const options=[...new Set(products.map(p=>p.category))].map(c=>`<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join(''); return pageShell('作品商城', `${nav()}<main class="page"><div class="page-intro"><div><div class="eyebrow">作品商城 / SHOP</div><h1>选一幅，写进日子里。</h1></div><p>商品类型与用途场景分开看。测试版的价格、图片、库存均可能是演示数据。</p></div><div class="filters"><label>用途场景<select id="category-filter"><option value="">全部场景</option>${options}</select></label><label>商品类型<select id="type-filter"><option value="">全部类型</option><option>手写原作</option><option>手写定制</option><option>艺术衍生品</option></select></label><label>排序<select id="sort-filter"><option value="default">默认</option><option value="low">价格从低到高</option><option value="high">价格从高到低</option></select></label></div><div class="product-grid" id="shop-grid">${products.map(productCard).join('')}</div><p class="empty hidden" id="empty-state">还没有符合条件的演示商品。</p></main>${footer()}<script>const categoryFilter=document.querySelector('#category-filter'),typeFilter=document.querySelector('#type-filter'),sortFilter=document.querySelector('#sort-filter'),grid=document.querySelector('#shop-grid'),empty=document.querySelector('#empty-state');const defaultOrder=[...grid.children];function render(){const cards=[...grid.children];cards.forEach(card=>card.classList.toggle('hidden',Boolean((categoryFilter.value&&card.dataset.category!==categoryFilter.value)||(typeFilter.value&&card.dataset.type!==typeFilter.value))));const visible=cards.filter(card=>!card.classList.contains('hidden'));if(sortFilter.value==='default')defaultOrder.forEach(card=>grid.appendChild(card));else visible.sort((a,b)=>(Number(a.dataset.price)-Number(b.dataset.price))*(sortFilter.value==='high'?-1:1)).forEach(card=>grid.appendChild(card));empty.classList.toggle('hidden',visible.length>0)}[categoryFilter,typeFilter,sortFilter].forEach(el=>el.addEventListener('change',render));</script>${cartScript()}`); }
function detailPage(product) { const p=publicProduct(product); const specs=p.specs.map(spec=>`<option value="${escapeHtml(spec.id)}">${escapeHtml(spec.label)}</option>`).join(''); return pageShell(p.name, `${nav()}<main class="page detail"><a class="back" href="/shop">← 返回商城</a><div class="detail-grid"><div><button class="image-button" id="image-open" type="button"><img class="detail-image" src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}（演示素材）"></button><p class="asset-note">待替换真实作品图；当前为测试构图，不代表斗升小民原作。点击图片可放大查看。</p></div><div><div class="eyebrow">${escapeHtml(p.type)} · ${escapeHtml(p.category)} · ${escapeHtml(p.status)}</div><h1>${escapeHtml(p.name)}</h1><p class="detail-lead">${escapeHtml(p.description)}</p><div class="spec-table"><div><span>工艺</span><b id="craft-value">${escapeHtml(p.craft)}</b></div><div><span>材质</span><b id="material-value">${escapeHtml(p.material)}</b></div><div><span>规格</span><b id="size-value">${escapeHtml(p.size)}</b></div><div><span>库存</span><b>${p.stock}（测试值）</b></div></div><label class="field-label">选择规格<select id="spec-id">${specs}</select></label><div class="price-large">演示价 ¥${p.price}</div><p class="muted">此价格不代表正式定价；配送、交期、售后政策待确认。</p><div class="buy-row"><label>数量<input id="quantity" type="number" min="1" max="${p.unique?1:p.stock}" value="1"></label><button class="button" id="add" type="button">加入购物车</button></div><div id="add-message" class="form-message" role="status"></div><div class="notice">${p.type === '艺术衍生品' ? '这是演示印品，不是手写原作。' : '真实商品的编号、视频、装裱与重写规则需逐件确认后启用。'}</div></div></div></main><dialog id="image-dialog"><button type="button" class="dialog-close">关闭</button><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)} 放大图"></dialog>${footer()}<script>const product=${safeJson({id:p.id,stock:p.stock,unique:p.unique,image:p.image,specs:p.specs})};const specSelect=document.querySelector('#spec-id');function setSpec(){const spec=product.specs.find(item=>item.id===specSelect.value)||product.specs[0];for(const [id,value] of [['craft-value',spec.craft],['material-value',spec.material],['size-value',spec.size]])document.querySelector('#'+id).textContent=value}specSelect.addEventListener('change',setSpec);setSpec();document.querySelector('#add').addEventListener('click',()=>{const quantity=Number(document.querySelector('#quantity').value);if(!Number.isSafeInteger(quantity)||quantity<1||quantity>(product.unique?1:product.stock)){document.querySelector('#add-message').textContent='请输入有效数量';return}const cart=cartRead();const specId=specSelect.value;const existing=cart.find(i=>i.id===product.id&&i.specId===specId);if(existing)existing.quantity=Math.min(product.stock,existing.quantity+quantity);else cart.push({id:product.id,specId,quantity});localStorage.setItem('xiaominart_cart',JSON.stringify(cart));document.querySelector('#add-message').textContent='已加入测试购物车';updateCartCount()});const dialog=document.querySelector('#image-dialog');document.querySelector('#image-open').onclick=()=>dialog.showModal();document.querySelector('.dialog-close').onclick=()=>dialog.close();</script>${cartScript()}`); }
function formPage(title, heading, intro, fields, endpoint, resultText) { return pageShell(title, `${nav()}<main class="page narrow"><div class="eyebrow">${escapeHtml(title)} / XIAOMINART</div><h1>${escapeHtml(heading)}</h1><p class="lead">${escapeHtml(intro)}</p><form id="submission-form" class="form-card">${fields}<button class="button" type="submit">提交测试内容</button><div id="form-result" class="form-message" role="status"></div></form></main>${footer()}${cartScript()}<script>const form=document.querySelector('#submission-form'),result=document.querySelector('#form-result'),button=form.querySelector('button');form.addEventListener('submit',async event=>{event.preventDefault();button.disabled=true;result.textContent='正在提交，请勿重复点击…';const key=form.dataset.idem||crypto.randomUUID();form.dataset.idem=key;try{const response=await fetch('${endpoint}',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok)throw new Error(data.error||'提交失败');result.textContent='${resultText} '+(data.requestNumber||data.id||'');form.reset();form.dataset.idem='';}catch(error){result.textContent=error.message+'；输入已保留，请检查网络后重试。';}finally{button.disabled=false}});</script>`); }
function customPage() { return pageShell('定制我的心意', `${nav()}<main class="page narrow"><div class="page-intro"><div><div class="eyebrow">定制指南 / CUSTOM</div><h1>把你的话，写成你的字。</h1></div><p>先需求、后人工报价。期望日期只代表需求，不等于已承诺交期。</p></div><div class="process"><span>01 告诉我场景</span><span>02 说说想写什么</span><span>03 生成需求编号</span><span>04 后台人工处理</span></div><form id="custom-form" class="form-card"><label>怎么称呼？<input name="name" required maxlength="60" placeholder="演示客户姓名"></label><label>联系方式（演示）<input name="contact" required maxlength="100" placeholder="demo@example.com"></label><label>写给谁？<select name="recipient"><option>给自己</option><option>给家人</option><option>给朋友</option><option>婚庆/乔迁/开业</option><option>其他</option></select></label><label>使用场景<select name="scene"><option>自勉与心事</option><option>书房与日常</option><option>婚庆</option><option>乔迁</option><option>开业</option><option>祝寿</option><option>新年与节庆</option></select></label><label>想写的文字<textarea name="text" required maxlength="500" placeholder="例如：福、上善若水，或你想说的一句话"></textarea></label><label>你的故事（可选，默认私密）<textarea name="story" maxlength="1000" placeholder="不填也能提交；不会自动公开"></textarea></label><label>预算区间（演示）<select name="budget"><option>待人工报价</option><option>¥39–99（演示）</option><option>¥100–299（演示）</option><option>¥300–999（演示）</option><option>¥1000以上（演示）</option></select></label><label>期望日期（需求，不是承诺）<input name="date" type="date"></label><label class="check"><input name="publicConsent" type="checkbox"> 我愿意进一步沟通公开事宜（不等于已授权公开）</label><button class="button" type="submit">提交测试需求</button><div id="custom-result" class="form-message" role="status"></div></form></main>${footer()}${cartScript()}<script>const form=document.querySelector('#custom-form'),result=document.querySelector('#custom-result'),button=form.querySelector('button');form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;result.textContent='正在提交，请勿重复点击…';const key=form.dataset.idem||crypto.randomUUID();form.dataset.idem=key;const data=Object.fromEntries(new FormData(form));data.publicConsent=Boolean(data.publicConsent);try{const r=await fetch('/api/custom-requests',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify(data)});const response=await r.json();if(!r.ok)throw new Error(response.error||'提交失败');result.textContent='需求已提交，编号：'+response.requestNumber;form.reset();form.dataset.idem='';}catch(error){result.textContent=error.message+'；输入已保留，请检查网络后重试。';}finally{button.disabled=false}});</script>`); }
function cartPage() { return pageShell('购物车', `${nav()}<main class="page narrow"><div class="eyebrow">购物车 / CART</div><h1>确认你的测试选择。</h1><div id="cart-view" aria-live="polite"></div></main>${footer()}<script>function cartRead(){try{const value=JSON.parse(localStorage.getItem('xiaominart_cart')||'[]');return Array.isArray(value)?value.filter(i=>i&&typeof i.id==='string'&&Number.isSafeInteger(i.quantity)&&i.quantity>0):[]}catch{return[]}}function updateCartCount(){const el=document.querySelector('#cart-count');if(el)el.textContent=String(cartRead().reduce((n,i)=>n+i.quantity,0))}const products=${safeJson(db.products.filter(p=>p.published).map(publicProduct))};const view=document.querySelector('#cart-view');function saveCart(cart){localStorage.setItem('xiaominart_cart',JSON.stringify(cart));updateCartCount()}function renderCart(){const cart=cartRead(),available=[];let total=0;view.replaceChildren();if(!cart.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='购物车还是空的。';const link=document.createElement('a');link.className='text-link';link.href='/shop';link.textContent='去商城看看 →';empty.append(document.createElement('br'),link);view.append(empty);return}for(const item of cart){const product=products.find(p=>p.id===item.id);if(!product||!product.published||product.stock<1){const note=document.createElement('div');note.className='notice';note.textContent='购物车中有商品已下架或缺货，请移除后继续。';view.append(note);continue}const max=product.unique?1:product.stock;const row=document.createElement('div');row.className='cart-row';const image=document.createElement('img');image.src=product.image;image.alt=product.name+'（演示素材）';const info=document.createElement('div');const name=document.createElement('b');name.textContent=product.name;const spec=document.createElement('p');spec.textContent=(product.specs.find(s=>s.id===item.specId)||product.specs[0]).label;const qty=document.createElement('input');qty.className='cart-qty';qty.type='number';qty.min='1';qty.max=String(max);qty.value=String(Math.min(item.quantity,max));qty.setAttribute('aria-label',product.name+'数量');qty.onchange=()=>{const value=Number(qty.value);if(!Number.isSafeInteger(value)||value<1||value>max){qty.value=String(Math.min(Math.max(1,value||1),max));return}const next=cart.map(i=>i===item?{...i,quantity:value}:i);saveCart(next);renderCart()};const line=document.createElement('p');line.textContent='演示价 ¥'+product.price+' × ';line.append(qty);info.append(name,spec,line);const remove=document.createElement('button');remove.type='button';remove.className='text-button';remove.textContent='移除';remove.onclick=()=>{saveCart(cart.filter(i=>i!==item));renderCart()};row.append(image,info,remove);view.append(row);available.push(item);total+=product.price*qty.value}if(!available.length)return;const actions=document.createElement('div');actions.className='cart-actions';const totalEl=document.createElement('div');totalEl.className='cart-total';totalEl.textContent='演示合计 ¥'+total;const clear=document.createElement('button');clear.type='button';clear.className='button secondary';clear.textContent='清空购物车';clear.onclick=()=>{saveCart([]);renderCart()};const checkout=document.createElement('a');checkout.className='button';checkout.href='/checkout';checkout.textContent='去测试结算';actions.append(totalEl,clear,checkout);view.append(actions)}renderCart();</script>${cartScript()}`); }
function checkoutPage() { return pageShell('测试结算', `${nav()}<main class="page narrow"><div class="eyebrow">测试结算 / CHECKOUT</div><h1>只使用虚拟信息。</h1><p class="lead">不会收集银行卡资料，不会产生真实扣款。地址和联系方式仅用于验证流程。</p><form id="checkout-form" class="form-card"><label>虚拟客户姓名<input name="name" required maxlength="80" value="测试客户"></label><label>虚拟联系方式<input name="contact" required maxlength="120" value="demo@example.com"></label><label>虚拟收货地址<textarea name="address" required maxlength="240">测试地址，不用于真实配送</textarea></label><label>模拟支付结果<select name="payment"><option value="success">模拟成功</option><option value="failure">模拟失败</option><option value="cancelled">模拟取消</option></select></label><label class="check"><input name="agree" type="checkbox" required> 我了解这是测试站，订单不产生真实付款或履约</label><button class="button" type="submit">创建测试订单</button><div id="checkout-result" class="form-message" role="status"></div></form></main>${footer()}${cartScript()}<script>const checkoutForm=document.querySelector('#checkout-form'),checkoutResult=document.querySelector('#checkout-result'),checkoutButton=checkoutForm.querySelector('button');checkoutForm.addEventListener('submit',async e=>{e.preventDefault();const cart=cartRead();if(!cart.length){checkoutResult.textContent='购物车为空，请返回商城选择商品';return}checkoutButton.disabled=true;checkoutResult.textContent='正在创建测试订单，请勿重复点击…';const key=checkoutForm.dataset.idem||crypto.randomUUID();checkoutForm.dataset.idem=key;const data=Object.fromEntries(new FormData(checkoutForm));try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify({customer:data,items:cart,payment:data.payment})});const response=await r.json();if(!r.ok)throw new Error(response.error||'提交失败');localStorage.removeItem('xiaominart_cart');location.href='/order/'+response.accessToken}catch(error){checkoutResult.textContent=error.message+'；输入已保留，可安全重试。';}finally{checkoutButton.disabled=false}});</script>`); }
function orderPage(tokenValue) { return pageShell('测试订单结果', `${nav()}<main class="page narrow"><div id="order-view" class="loading">正在读取测试订单…</div></main>${footer()}<script>const target=document.querySelector('#order-view');fetch('/api/orders/${escapeHtml(tokenValue)}').then(r=>r.json()).then(order=>{target.replaceChildren();if(order.error){const note=document.createElement('div');note.className='notice';note.textContent=order.error;target.append(note);return}const eyebrow=document.createElement('div');eyebrow.className='eyebrow';eyebrow.textContent='订单结果';const title=document.createElement('h1');title.textContent=order.orderNumber;const lead=document.createElement('p');lead.className='lead';lead.textContent=order.paymentMessage;const card=document.createElement('div');card.className='order-card';const status=document.createElement('b');status.textContent='状态：'+order.status;const total=document.createElement('p');total.textContent='演示金额：'+order.currency+' '+order.total;const items=document.createElement('p');items.textContent='商品：'+order.items.map(item=>item.name+' · '+item.specLabel+' × '+item.quantity).join('、');const note=document.createElement('p');note.className='muted';note.textContent='这是测试订单，不是实际收入，不会发货。';card.append(status,total,items,note);target.append(eyebrow,title,lead,card)}).catch(()=>{target.textContent='读取失败，请稍后重试'})</script>`); }
function contentPage(kind) { const pages={craft:['工艺与故事','工艺说清楚，心意才站得住。','手写原作、手写定制、艺术衍生品，测试版按真实工艺分开标注。'],about:['关于小民','斗升小民，是小民艺术的书写者。','我不替大师写字，我替每一个普通人写字。个人履历、师承、城市和真实创作者照片待补充与确认。'],contact:['联系与帮助','有想写的话，可以先告诉小民。','当前是测试站，不提供真实付款和正式订单履约。正式联系方式、配送范围、售后政策待确认。']}[kind];return pageShell(pages[0],`${nav()}<main class="page narrow prose-page"><div class="eyebrow">${pages[0]} / XIAOMINART</div><h1>${pages[1]}</h1><p class="lead">${pages[2]}</p><div class="story-box"><b>心事有人听 · 喜事有人乐。</b><p>缺少真实素材时，测试站不会用 AI 生成书法冒充原作，也不会编造客户故事、销量、资质或评价。</p></div>${kind==='contact'?'<a class="button" href="/custom">提交测试定制需求</a>':''}</main>${footer()}${cartScript()}`); }
function policyPage(kind) { const data={privacy:['隐私说明','测试版只处理演示表单中的虚拟信息。真实隐私政策待经营者确认。','测试阶段不导入真实客户数据、不接真实付款、不用于发货。正式上线前需确认收集字段、保存期限、访问权限、删除与投诉方式。'],terms:['销售条款','当前不构成正式销售条款。','商品、价格、支付、交付、退款与争议解决规则待经营者确认，测试订单不产生真实收入。'],shipping:['配送说明','当前不承诺配送。','销售地区、配送范围、运费、交期和不可配送区域待经营者确认。测试地址不会用于真实配送。'], 'after-sales':['售后说明','当前不构成正式售后政策。','重写、退换、退款、定制取消与破损处理规则待经营者确认。']}[kind];return pageShell(data[0],`${nav()}<main class="page narrow prose-page"><div class="eyebrow">${data[0]} / 待确认</div><h1>${data[1]}</h1><p class="lead">${data[2]}</p><div class="notice">本页是必要结构占位，不代表已作出商业承诺。</div></main>${footer()}${cartScript()}`); }
function submissionPage(title, message) { return formPage(title,title,message,'<label>怎么称呼？<input name="name" required maxlength="80"></label><label>联系方式（演示）<input name="contact" required maxlength="120"></label><label>内容<textarea name="message" required maxlength="1000"></textarea></label><input type="hidden" name="publicConsent" value="false">','/api/submissions','已收录，默认待人工审核，编号：'); }
function adminLoginPage() { return pageShell('管理员登录', `${nav()}<main class="page narrow"><div class="eyebrow">ADMIN LOGIN</div><h1>测试后台登录</h1><p class="lead">测试共享请使用独立账号。密码不会预填。</p><form id="login" class="form-card"><label>账号<input name="username" required autocomplete="username"></label><label>密码<input name="password" type="password" required autocomplete="current-password"></label><button class="button" type="submit">登录后台</button><div id="result" class="form-message" role="status"></div></form></main>${footer()}${cartScript()}<script>document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,result=document.querySelector('#result');const response=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(response.ok)location.href='/admin';else result.textContent=(await response.json()).error||'登录失败'}</script>`); }
function adminPage() { return pageShell('管理后台', `${nav()}<main class="page admin-page"><div class="page-intro"><div><div class="eyebrow">ADMIN / TEST DATA</div><h1>小民艺术测试后台</h1></div><button class="button secondary" id="logout" type="button">退出登录</button></div><div id="admin-data" class="loading">正在加载…</div></main>${footer()}<script>const root=document.querySelector('#admin-data');const statusOptions={order:['paid','fulfilled','cancelled'],custom:['新提交','已联系','报价中','已完成','已关闭'],submission:['待人工审核','已审核','已拒绝']};function el(tag,text='',className=''){const node=document.createElement(tag);node.textContent=text;if(className)node.className=className;return node}async function api(url,options={}){const r=await fetch(url,options);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'操作失败');return data}function selectFor(values,current,onchange){const select=document.createElement('select');values.forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;option.selected=value===current;select.append(option)});select.onchange=onchange;return select}async function load(){try{const d=await api('/api/admin/summary');root.replaceChildren();const stats=el('div','', 'admin-grid');[['商品',d.products.length],['测试订单',d.orders.length],['定制需求',d.customRequests.length],['投稿',d.submissions.length]].forEach(([name,value])=>{const box=el('div','', 'stat');box.append(el('span',name),el('b',String(value)));stats.append(box)});root.append(stats);const productSection=el('section','', 'admin-section');productSection.append(el('h2','商品与库存'));d.products.forEach(product=>{const row=el('div','', 'admin-row');row.append(el('b',product.id+' · '+product.name));const price=document.createElement('input');price.type='number';price.min='0';price.value=product.price;price.setAttribute('aria-label',product.name+'价格');const stock=document.createElement('input');stock.type='number';stock.min='0';stock.max=product.unique?'1':'9999';stock.value=product.stock;stock.setAttribute('aria-label',product.name+'库存');const published=document.createElement('input');published.type='checkbox';published.checked=product.published;published.setAttribute('aria-label',product.name+'上架');const save=document.createElement('button');save.className='button small';save.textContent='保存';const msg=el('small','');save.onclick=async()=>{save.disabled=true;try{await api('/api/admin/products/'+encodeURIComponent(product.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({price:Number(price.value),stock:Number(stock.value),published:published.checked})});msg.textContent='已保存';await load()}catch(error){msg.textContent=error.message}finally{save.disabled=false}};row.append(el('span','演示价'),price,el('span','库存'),stock,el('label','上架 '+(published.checked?'是':'否')),published,save,msg);productSection.append(row)});root.append(productSection);const orderSection=el('section','', 'admin-section');orderSection.append(el('h2','订单处理'));d.orders.forEach(order=>{const row=el('div','', 'admin-row');row.append(el('b',order.orderNumber),el('span',order.items.map(item=>item.name+' × '+item.quantity).join('、')+' · '+order.total+' '+order.currency));const select=selectFor(statusOptions.order,order.orderStatus,async()=>{try{await api('/api/admin/orders/'+encodeURIComponent(order.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:select.value})});await load()}catch(error){msg.textContent=error.message}});const msg=el('small',order.paymentMessage);row.append(select,msg);orderSection.append(row)});root.append(orderSection);const customSection=el('section','', 'admin-section');customSection.append(el('h2','定制需求'));d.customRequests.forEach(request=>{const row=el('div','', 'admin-row');row.append(el('b',request.requestNumber),el('span',request.text));const select=selectFor(statusOptions.custom,request.status,async()=>{try{await api('/api/admin/custom-requests/'+encodeURIComponent(request.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:select.value})});await load()}catch(error){msg.textContent=error.message}});const msg=el('small',request.name+' · '+request.contact);row.append(select,msg);customSection.append(row)});root.append(customSection);const submissionSection=el('section','', 'admin-section');submissionSection.append(el('h2','小民信箱 / 小民喜报投稿'));d.submissions.forEach(item=>{const row=el('div','', 'admin-row');row.append(el('b',item.id.slice(0,8)),el('span',item.message));const select=selectFor(statusOptions.submission,item.status,async()=>{try{await api('/api/admin/submissions/'+encodeURIComponent(item.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:select.value})});await load()}catch(error){msg.textContent=error.message}});const msg=el('small',item.name+' · '+item.contact);row.append(select,msg);submissionSection.append(row)});root.append(submissionSection)}catch(error){root.textContent=error.message}}load();document.querySelector('#logout').onclick=async()=>{await fetch('/api/admin/logout',{method:'POST'});location.href='/admin/login'}</script>`); }

async function handleApi(req, res, url) {
  if (req.method === 'POST' && url.pathname === '/api/admin/login') { const data = await body(req); if (data && typeof data.username === 'string' && data.username === ADMIN_USER && typeof data.password === 'string' && data.password === ADMIN_PASSWORD) { const session=token();sessions.set(session,{expires:Date.now()+SESSION_TTL});res.writeHead(200,{'Set-Cookie':`xiaominart_session=${session}; HttpOnly; SameSite=Lax; Path=/; Max-Age=${SESSION_TTL/1000}`,'Content-Type':'application/json'});res.end(JSON.stringify({ok:true})); } else json(res,401,{error:'账号或密码错误'});return; }
  if (req.method === 'POST' && url.pathname === '/api/admin/logout') { const cookies=parseCookies(req);sessions.delete(cookies.xiaominart_session);res.writeHead(200,{'Set-Cookie':'xiaominart_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0','Content-Type':'application/json'});res.end(JSON.stringify({ok:true}));return; }
  if (url.pathname === '/api/products' && req.method === 'GET') { json(res,200,db.products.filter(p=>p.published).map(publicProduct));return; }
  if (url.pathname.startsWith('/api/products/') && req.method === 'GET') { const product=db.products.find(p=>p.slug===url.pathname.slice('/api/products/'.length)); if(!product||!product.published)json(res,404,{error:'商品不存在或暂不可售'});else json(res,200,publicProduct(product));return; }
  if (url.pathname === '/api/custom-requests' && req.method === 'POST') { const data=await body(req),allowed=['name','contact','recipient','scene','text','story','budget','date','publicConsent'];if(!data||typeof data.name!=='string'||typeof data.contact!=='string'||typeof data.text!=='string')return json(res,400,{error:'请填写姓名、联系方式和想写的文字'});const requestData={name:data.name.trim().slice(0,60),contact:data.contact.trim().slice(0,100),recipient:typeof data.recipient==='string'?data.recipient.trim().slice(0,40):'',scene:typeof data.scene==='string'?data.scene.trim().slice(0,40):'',text:data.text.trim().slice(0,500),story:typeof data.story==='string'?data.story.trim().slice(0,1000):'',budget:typeof data.budget==='string'?data.budget.trim().slice(0,40):'',date:typeof data.date==='string'?data.date.slice(0,10):'',publicConsent:Boolean(data.publicConsent)};if(!requestData.name||!requestData.contact||!requestData.text)return json(res,400,{error:'姓名、联系方式和文字不能为空'});const key=requestKey(req,`custom-${randomUUID()}`),existing=getIdempotent('custom',key,requestData);if(existing?.conflict)return json(res,409,{error:'同一幂等键对应了不同内容'});if(existing)return json(res,existing.status,existing.body);const request={id:randomUUID(),requestNumber:orderNumber('CUSTOM'),...requestData,status:'新提交',createdAt:new Date().toISOString()};try{begin();saveCustom(request);saveIdempotent('custom',key,requestData,201,request);saveEvent('custom_request_submitted',{requestNumber:request.requestNumber});commit();json(res,201,request)}catch(error){rollback();console.error(error);json(res,500,{error:'提交未确认，请安全重试'})}return; }
  if (url.pathname === '/api/orders' && req.method === 'POST') { const data=await body(req),preview=orderPreview(data);if(preview.error)return json(res,/库存|不可售|独件/.test(preview.error)?409:400,{error:preview.error});const idemPayload={customer:preview.customer,items:preview.items.map(i=>({id:i.id,specId:i.specId,quantity:i.quantity})),payment:preview.payment};const key=requestKey(req,`order-${randomUUID()}`),existing=getIdempotent('order',key,idemPayload);if(existing?.conflict)return json(res,409,{error:'同一幂等键对应了不同内容'});if(existing)return json(res,existing.status,existing.body);const orderStatus=preview.payment==='success'?'paid':preview.payment==='failure'?'failed':'cancelled';const order={id:randomUUID(),orderNumber:orderNumber('TEST'),accessToken:token(),customer:preview.customer,items:preview.items,total:preview.total,currency:'CNY',payment:preview.payment,paymentStatus:'simulated_'+preview.payment,orderStatus,statusText:stateText(orderStatus),paymentMessage:preview.payment==='success'?'内部模拟支付成功（不代表真实付款）':preview.payment==='failure'?'内部模拟支付失败，未创建成功收入':'内部模拟支付已取消，未创建成功收入',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};try{begin();if(preview.payment==='success')for(const item of preview.items){const product=productById(item.id);if(!product||!product.published||product.stock<item.quantity)throw new Error('库存已变化，请刷新后重试');if(product.unique&&product.stock!==1)throw new Error('独件库存规则不允许当前库存');product.stock-=item.quantity;saveProduct(product)}saveOrder(order);const response={orderNumber:order.orderNumber,accessToken:order.accessToken,status:order.statusText};saveIdempotent('order',key,idemPayload,201,response);saveEvent('test_order_created',{orderNumber:order.orderNumber,orderStatus});commit();json(res,201,response)}catch(error){rollback();json(res,409,{error:error.message==='库存已变化，请刷新后重试'?error.message:'订单未创建，请重试'})}return; }
  if (url.pathname.startsWith('/api/orders/') && req.method === 'GET') { const raw=url.pathname.slice('/api/orders/'.length);if(!/^[a-f0-9]{48}$/.test(raw))return json(res,404,{error:'订单不存在或访问令牌无效'});const order=db.orders.find(item=>item.accessToken===raw);if(!order)return json(res,404,{error:'订单不存在或访问令牌无效'});json(res,200,{orderNumber:order.orderNumber,orderStatus:order.orderStatus,status:order.statusText,paymentMessage:order.paymentMessage,total:order.total,currency:order.currency,items:order.items.map(i=>({name:i.name,specLabel:i.specLabel,quantity:i.quantity,price:i.price}))});return; }
  if (url.pathname === '/api/submissions' && req.method === 'POST') { const data=await body(req);if(!data||typeof data.name!=='string'||typeof data.contact!=='string'||typeof data.message!=='string')return json(res,400,{error:'请填写称呼、联系方式和投稿内容'});const itemData={name:data.name.trim().slice(0,80),contact:data.contact.trim().slice(0,120),message:data.message.trim().slice(0,1000)};if(!itemData.name||!itemData.contact||!itemData.message)return json(res,400,{error:'称呼、联系方式和投稿内容不能为空'});const key=requestKey(req,`submission-${randomUUID()}`),existing=getIdempotent('submission',key,itemData);if(existing?.conflict)return json(res,409,{error:'同一幂等键对应了不同内容'});if(existing)return json(res,existing.status,existing.body);const item={id:randomUUID(),...itemData,publicConsent:false,status:'待人工审核',createdAt:new Date().toISOString()};try{begin();saveSubmission(item);saveIdempotent('submission',key,itemData,201,item);saveEvent('submission_received');commit();json(res,201,item)}catch{rollback();json(res,500,{error:'投稿未确认，请安全重试'})}return; }
  if (url.pathname.startsWith('/api/admin/') && !requireAuth(req,res)) return;
  if (url.pathname === '/api/admin/summary' && req.method === 'GET') { json(res,200,{products:db.products.map(publicProduct),orders:db.orders,customRequests:db.customRequests,submissions:db.submissions,events:db.events});return; }
  if (url.pathname.startsWith('/api/admin/products/') && req.method === 'PATCH') { const id=url.pathname.slice('/api/admin/products/'.length);const product=productById(id),data=await body(req);if(!product||!data||Object.keys(data).some(key=>!['price','stock','published'].includes(key)))return json(res,400,{error:'商品字段无效'});const next={...product};if(data.price!==undefined&&(!Number.isSafeInteger(data.price)||data.price<0))return json(res,400,{error:'价格必须是非负安全整数'});if(data.stock!==undefined&&(!Number.isSafeInteger(data.stock)||data.stock<0||(product.unique&&data.stock>1)))return json(res,400,{error:product.unique?'独件库存只能为 0 或 1':'库存必须是非负安全整数'});if(data.price!==undefined)next.price=data.price;if(data.stock!==undefined)next.stock=data.stock;if(data.published!==undefined)next.published=data.published===true;try{begin();saveProduct(next);saveEvent('admin_product_updated',{id});commit();json(res,200,publicProduct(next))}catch{rollback();json(res,500,{error:'商品未保存，请重试'})}return; }
  if (url.pathname.startsWith('/api/admin/orders/') && req.method === 'PATCH') { const id=url.pathname.slice('/api/admin/orders/'.length),data=await body(req),order=db.orders.find(item=>item.id===id);if(!order||!data||typeof data.status!=='string'||!allowedOrderTransition(order.orderStatus,data.status))return json(res,409,{error:'订单状态转换不允许'});try{const from=order.orderStatus;begin();if(from==='paid'&&data.status==='cancelled'){for(const item of order.items){const product=productById(item.id);product.stock+=item.quantity;if(product.unique&&product.stock>1)throw new Error('独件库存恢复规则冲突');saveProduct(product)}}order.orderStatus=data.status;order.statusText=stateText(data.status);if(data.status==='cancelled'&&order.payment==='success')order.paymentMessage='订单已取消；原状态为内部模拟支付成功，不代表真实付款';order.updatedAt=new Date().toISOString();updateOrder(order);saveEvent('admin_order_status_changed',{id,from,to:data.status});commit();json(res,200,order)}catch(error){rollback();json(res,409,{error:error.message||'订单状态未保存'})}return; }
  if (url.pathname.startsWith('/api/admin/custom-requests/') && req.method === 'PATCH') { const id=url.pathname.slice('/api/admin/custom-requests/'.length),data=await body(req),request=db.customRequests.find(item=>item.id===id),allowed=['新提交','已联系','报价中','已完成','已关闭'];if(!request||!data||!allowed.includes(data.status))return json(res,409,{error:'定制需求状态无效'});try{begin();request.status=data.status;request.updatedAt=new Date().toISOString();updateCustom(request);saveEvent('admin_custom_status_changed',{id,status:data.status});commit();json(res,200,request)}catch{rollback();json(res,500,{error:'定制需求未保存，请重试'})}return; }
  if (url.pathname.startsWith('/api/admin/submissions/') && req.method === 'PATCH') { const id=url.pathname.slice('/api/admin/submissions/'.length),data=await body(req),item=db.submissions.find(value=>value.id===id),allowed=['待人工审核','已审核','已拒绝'];if(!item||!data||!allowed.includes(data.status))return json(res,409,{error:'投稿状态无效'});try{begin();item.status=data.status;item.updatedAt=new Date().toISOString();sqlite.prepare('UPDATE submissions SET data=? WHERE id=?').run(JSON.stringify(item),id);saveEvent('admin_submission_status_changed',{id,status:data.status});commit();json(res,200,item)}catch{rollback();json(res,500,{error:'投稿未保存，请重试'})}return; }
  json(res,404,{error:'API not found'});
}

const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,`http://${req.headers.host||'localhost'}`);if(url.pathname.startsWith('/api/'))return await handleApi(req,res,url);if(url.pathname==='/styles.css'){res.writeHead(200,{'Content-Type':'text/css; charset=utf-8'});res.end(await readFile(path.join(ROOT,'styles.css')));return}if(url.pathname.startsWith('/assets/')){const name=path.basename(url.pathname);if(!['fu.svg','lu.svg','shou.svg','xi.svg','cai.svg'].includes(name))return res.writeHead(404).end();try{res.writeHead(200,{'Content-Type':'image/svg+xml'});res.end(await readFile(path.join(ROOT,'assets',name)))}catch{res.writeHead(404).end()}return}if(url.pathname==='/')return html(res,homePage());if(url.pathname==='/shop')return html(res,shopPage());if(url.pathname.startsWith('/shop/')){const slug=decodeURIComponent(url.pathname.slice('/shop/'.length));const product=db.products.find(p=>p.slug===slug&&p.published);return product?html(res,detailPage(product)):html(res,pageShell('未找到',`${nav()}<main class="page"><h1>商品不存在或暂不可售</h1></main>${footer()}`),404)}if(url.pathname==='/custom')return html(res,customPage());if(url.pathname==='/craft'||url.pathname==='/about'||url.pathname==='/contact')return html(res,contentPage(url.pathname.slice(1)));if(['privacy','terms','shipping','after-sales'].includes(url.pathname.slice(1)))return html(res,policyPage(url.pathname.slice(1)));if(url.pathname==='/inbox')return html(res,submissionPage('小民信箱','把一件小事、一句话或一段心事写给小民。'));if(url.pathname==='/good-news')return html(res,submissionPage('小民喜报','分享一件值得一起高兴的日子。'));if(url.pathname==='/cart')return html(res,cartPage());if(url.pathname==='/checkout')return html(res,checkoutPage());if(url.pathname.startsWith('/order/')){const raw=decodeURIComponent(url.pathname.slice('/order/'.length));return /^[a-f0-9]{48}$/.test(raw)?html(res,orderPage(raw)):html(res,pageShell('未找到',`${nav()}<main class="page"><h1>订单不存在</h1></main>${footer()}`),404)}if(url.pathname==='/admin/login')return html(res,adminLoginPage());if(url.pathname==='/admin')return authenticated(req)?html(res,adminPage()):redirect(res,'/admin/login');return html(res,pageShell('未找到',`${nav()}<main class="page"><h1>页面不存在</h1><a href="/">回到首页</a></main>${footer()}`),404)}catch(error){console.error(error);json(res,500,{error:'服务器错误'})}});
server.listen(PORT,()=>console.log(`xiaominART test site running at http://localhost:${PORT}`));
